269: /// Which items fit in `available` (order preserved); the rest go to the
270: /// overflow menu, whose button takes `overflow_width` when anything spills.
271: /// Every command stays reachable (handbook 16: "Toolbar actions all
272: /// accessible via visible buttons or overflow").
273: pub fn fit_toolbar(
274:     items: &[ToolbarSlot],
275:     available: f32,
276:     gap: f32,
277:     overflow_width: f32,
278: ) -> Vec<bool> {
279:     let total = |vis: &[bool], with_overflow: bool| {
280:         let mut w = 0.0;
281:         let mut n = 0;
282:         for (item, v) in items.iter().zip(vis) {
283:             if *v {
284:                 w += item.width;
285:                 n += 1;
286:             }
287:         }
288:         if with_overflow {
289:             w += overflow_width;
290:             n += 1;
291:         }
292:         w + gap * (n.max(1) - 1) as f32
293:     };
294:     let mut visible = vec![true; items.len()];
295:     if total(&visible, false) <= available {
296:         return visible;
297:     }
298:     let mut order: Vec<usize> = (0..items.len()).collect();
299:     // Lowest priority first; among equals, the rightmost first.
300:     order.sort_by(|a, b| items[*a].priority.cmp(&items[*b].priority).then(b.cmp(a)));
301:     for i in order {
302:         visible[i] = false;
303:         if total(&visible, true) <= available {
304:             break;
305:         }
306:     }
307:     visible
308: }
