    mod shell_geometry {
        use super::super::SANDCAT_SHELL_GEOMETRY;
        use silvestris::core::layout::{
            drag, plan, Divider, InspectorPreference, PlanInput, ShellPlan, SidebarPreference,
        };

        fn planned(viewport: f32, sidebar: SidebarPreference) -> ShellPlan {
            plan(PlanInput {
                viewport,
                geometry: SANDCAT_SHELL_GEOMETRY,
                sidebar,
                inspector: InspectorPreference {
                    visible: false,
                    pinned: true,
                    width: 320.0,
                },
                rail_enabled: false,
                previous: None,
            })
        }

        #[test]
        fn a_hidden_sidebar_consumes_no_pixels_at_either_window_width() {
            let hidden = SidebarPreference {
                expanded: false,
                width: 276.0,
            };
            for viewport in [640.0, 1280.0] {
                let plan = planned(viewport, hidden);
                assert_eq!(plan.sidebar.width, 0.0, "no substitute rail at {viewport}");
                assert_eq!(plan.workspace.x, 0.0, "workspace starts at the body edge");
                assert_eq!(plan.workspace.width, viewport);
            }
        }

        #[test]
        fn collapse_then_resize_then_reopen_restores_the_remembered_width() {
            let remembered = SidebarPreference {
                expanded: true,
                width: 276.0,
            };
            assert_eq!(planned(1280.0, remembered).sidebar.width, 276.0);

            let hidden = SidebarPreference {
                expanded: false,
                ..remembered
            };
            assert_eq!(planned(640.0, hidden).workspace.x, 0.0);

            let reopened = SidebarPreference {
                expanded: true,
                ..hidden
            };
            assert_eq!(planned(640.0, reopened).sidebar.width, 276.0);
            assert_eq!(planned(1280.0, reopened).sidebar.width, 276.0);
        }

        #[test]
        fn an_overwide_sidebar_is_narrowed_before_it_needs_to_disappear() {
            let wide = SidebarPreference {
                expanded: true,
                width: 440.0,
            };
            let plan = planned(640.0, wide);
            assert!(plan.sidebar_expanded);
            assert!(plan.sidebar_demoted);
            assert_eq!(plan.sidebar.width, 320.0);
            assert_eq!(plan.workspace.width, 320.0);
        }

        #[test]
        fn dragging_the_divider_past_the_collapse_threshold_preserves_the_width() {
            // Silvestris' divider reports `None` below sidebar_min / 2 and only
            // flips `expanded`; it never overwrites `SidebarPreference.width`.
            let collapsed = drag(
                Divider::Sidebar,
                &SANDCAT_SHELL_GEOMETRY,
                90.0,
                1280.0,
                0.0,
            );
            assert!(collapsed.is_none());
        }
    }
}

