fn render_agent_popup(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
    let snapshot = self.snapshot.as_ref()?;
    let current = self
        .current_summary()
        .and_then(|summary| summary.agent.clone());
    let agents: Vec<(String, SharedString)> = snapshot
        .agents
        .iter()
        .filter(|agent| agent.mode.selectable() && !agent.hidden)
        .map(|agent| (agent.id.clone(), SharedString::from(agent.name.clone())))
        .collect();
    let disabled = agents.is_empty();
    let selected = current
        .as_ref()
        .and_then(|current| agents.iter().position(|(id, _)| id == current));
    let items: Vec<SharedString> = agents.iter().map(|(_, name)| name.clone()).collect();
    let agent_ids: Vec<String> = agents.iter().map(|(id, _)| id.clone()).collect();
    let session = self.current_session();
    let this = cx.weak_entity();
    let popup = PopUpButton::new("toolbar-agent", "Agent", items)
        .selected(selected)
        .size(ControlSize::Regular)
        .bezel(PopupStyle::Textured)
        .min_width(96.)
        .disabled(disabled)
        .on_choose(move |index, _, cx| {
            let Some(id) = agent_ids.get(*index).cloned() else {
                return;
            };
            let Some(session) = session.clone() else {
                return;
            };
            let _ = this.update(cx, |view, cx| view.switch_agent_for(session, id, cx));
        });
    let anchor = self.agent_bounds.clone();
    let wrapped = div().relative().child(popup).child(
        gpui::canvas(
            |_, _, _| (),
            move |bounds, _, _, _| {
                anchor.set(bounds);
            },
        )
        .absolute()
        .inset_0(),
    );
    Some(toolbar_help(
        "toolbar-agent-help",
        if disabled {
            "This location has no selectable agents".to_owned()
        } else {
            "Choose the agent for this session (F3)".to_owned()
        },
        wrapped,
    ))
}

fn render_model_popup(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
    let snapshot = self.snapshot.as_ref()?;
    let server = snapshot.server;
    let current = self
        .current_summary()
        .and_then(|summary| summary.model.clone());
    let mut recents: Vec<ModelRef> = self
        .recent_models
        .get(&server)
        .map(|models| {
            available_recent_models(models, |model| {
                snapshot
                    .models
                    .iter()
                    .any(|info| info.enabled && model_ref_matches(info, model))
            })
        })
        .unwrap_or_default();
    if recents.is_empty() {
        if let Some(current) = current.clone() {
            recents.push(current);
        }
    }
    let mut labels: Vec<String> = recents
        .iter()
        .map(|model| self.model_display(model))
        .collect();
    for index in 0..labels.len() {
        if labels
            .iter()
            .enumerate()
            .filter(|(other, label)| *other != index && *label == &labels[index])
            .count()
            > 0
        {
            labels[index] =
                format!("{} \u{2014} {}", labels[index], recents[index].provider_id);
        }
    }
    labels.push(String::new());
    labels.push("Other Model…".into());
    let mut items: Vec<SharedString> = labels.into_iter().map(SharedString::from).collect();
    let separator = recents.len();
    let selected = current
        .as_ref()
        .and_then(|current| recents.iter().position(|model| model == current));
    let this = cx.weak_entity();
    let recents_for_choice = recents.clone();
    let popup = PopUpButton::new("toolbar-model", "Model", std::mem::take(&mut items))
        .selected(selected)
        .size(ControlSize::Regular)
        .bezel(PopupStyle::Textured)
        .min_width(120.)
        .unselectable([separator])
        .on_choose(move |index, window, cx| {
            let _ = this.update(cx, |view, cx| {
                if let Some(model) = recents_for_choice.get(*index).cloned() {
                    view.switch_session_model(model, cx);
                } else if *index > separator {
                    view.open_choose_model_sheet(window, cx);
                }
            });
        });
    Some(toolbar_help(
        "toolbar-model-help",
        "Choose the model for this session (Alt+P opens all models)",
        popup,
    ))
}

fn render_effort_popup(&self, cx: &mut Context<Self>) -> AnyElement {
    let variants: Vec<String> = self
        .current_model_variants()
        .map(|variants| variants.iter().map(|variant| variant.id.clone()).collect())
        .unwrap_or_default();
    let disabled = variants.is_empty();
    let mut items: Vec<SharedString> = vec!["Default".into()];
    items.extend(variants.iter().cloned().map(SharedString::from));
    let current = self
        .current_summary()
        .and_then(|summary| summary.model.as_ref())
        .and_then(|model| model.variant.clone());
    let selected = current
        .as_ref()
        .and_then(|current| variants.iter().position(|variant| variant == current))
        .map(|index| index + 1);
    let this = cx.weak_entity();
    let popup = PopUpButton::new("toolbar-effort", "Effort", items)
        .selected(selected.or(Some(0)))
        .size(ControlSize::Regular)
        .bezel(PopupStyle::Textured)
        .min_width(96.)
        .disabled(disabled)
        .on_choose(move |index, _, cx| {
            let variant = (*index)
                .checked_sub(1)
                .and_then(|index| variants.get(index).cloned());
            let _ = this.update(cx, |view, cx| view.set_model_variant(variant, cx));
        });
    let anchor = self.effort_bounds.clone();
    let wrapped = div().relative().child(popup).child(
        gpui::canvas(
            |_, _, _| (),
            move |bounds, _, _, _| {
                anchor.set(bounds);
            },
        )
        .absolute()
        .inset_0(),
    );
    toolbar_help(
        "toolbar-effort-help",
        if disabled {
            "The current model has no effort variants".to_owned()
        } else {
            "Choose the effort variant for the current model (Alt+E)".to_owned()
        },
        wrapped,
    )
}

