/// The composer control row: prompt-execution choices live beside the
/// prompt, not in window chrome. Each group is a small label and its
/// window-body pop-up; groups are separated by the normal control spacing.
fn render_composer_controls(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
    let theme = cx.theme().clone();
    let mut row = div()
        .flex()
        .flex_wrap()
        .items_center()
        .gap(px(theme.metrics.control_spacing));
    let mut rendered = false;
    if let Some(agent) = self.render_composer_agent(cx) {
        row = row.child(
            div()
                .flex()
                .items_center()
                .gap(px(theme.metrics.checkbox_label_gap))
                .child(
                    div()
                        .text_size(px(theme.type_.size_small))
                        .child("Agent:"),
                )
                .child(agent),
        );
        rendered = true;
    }
    if let Some(model) = self.render_composer_model(cx) {
        row = row.child(
            div()
                .flex()
                .items_center()
                .gap(px(theme.metrics.checkbox_label_gap))
                .child(
                    div()
                        .text_size(px(theme.type_.size_small))
                        .child("Model:"),
                )
                .child(model),
        );
        rendered = true;
    }
    if let Some(variant) = self.render_composer_variant(cx) {
        row = row.child(
            div()
                .flex()
                .items_center()
                .gap(px(theme.metrics.checkbox_label_gap))
                .child(
                    div()
                        .text_size(px(theme.type_.size_small))
                        .child("Variant:"),
                )
                .child(variant),
        );
        rendered = true;
    }
    rendered.then(|| row.into_any_element())
}

/// Agent selection for the active session. No active session or catalog
/// means no selector, rather than an empty textured box.
fn render_composer_agent(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
    let snapshot = self.snapshot.as_ref()?;
    self.current_summary()?;
    let current = self
        .current_summary()
        .and_then(|summary| summary.agent.clone());
    let agents: Vec<(String, SharedString)> = snapshot
        .agents
        .iter()
        .filter(|agent| agent.mode.selectable() && !agent.hidden)
        .map(|agent| (agent.id.clone(), SharedString::from(agent.name.clone())))
        .collect();
    if agents.is_empty() {
        return None;
    }
    let selected = current
        .as_ref()
        .and_then(|current| agents.iter().position(|(id, _)| id == current));
    let items: Vec<SharedString> = agents.iter().map(|(_, name)| name.clone()).collect();
    let agent_ids: Vec<String> = agents.iter().map(|(id, _)| id.clone()).collect();
    let session = self.current_session();
    let this = cx.weak_entity();
    let popup = PopUpButton::new("composer-agent", "Agent", items)
        .selected(selected)
        .size(ControlSize::Small)
        .min_width(96.)
        .on_choose(move |index, _, cx| {
            let Some(id) = agent_ids.get(*index).cloned() else {
                return;
            };
            let Some(session) = session.clone() else {
                return;
            };
            let _ = this.update(cx, |view, cx| view.switch_agent_for(session, id, cx));
        });
    let anchor = self.agent_bounds.clone();
    Some(
        div().relative().child(popup).child(
            gpui::canvas(
                |_, _, _| (),
                move |bounds, _, _, _| {
                    anchor.set(bounds);
                },
            )
            .absolute()
            .inset_0(),
        ),
    )
}

/// Recent models plus `Other Model…`; the full catalogue stays in the
/// existing sheet. Omitted until a session and a usable model are known.
fn render_composer_model(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
    let snapshot = self.snapshot.as_ref()?;
    self.current_summary()?;
    let server = snapshot.server;
    let current = self
        .current_summary()
        .and_then(|summary| summary.model.clone());
    let mut recents: Vec<ModelRef> = self
        .recent_models
        .get(&server)
        .map(|models| {
            available_recent_models(models, |model| {
                snapshot
                    .models
                    .iter()
                    .any(|info| info.enabled && model_ref_matches(info, model))
            })
        })
        .unwrap_or_default();
    if recents.is_empty() {
        if let Some(current) = current.clone() {
            recents.push(current);
        }
    }
    if recents.is_empty() {
        return None;
    }
    let mut labels: Vec<String> = recents
        .iter()
        .map(|model| self.model_display(model))
        .collect();
    for index in 0..labels.len() {
        if labels
            .iter()
            .enumerate()
            .filter(|(other, label)| *other != index && *label == &labels[index])
            .count()
            > 0
        {
            labels[index] =
                format!("{} \u{2014} {}", labels[index], recents[index].provider_id);
        }
    }
    labels.push(String::new());
    labels.push("Other Model…".into());
    let mut items: Vec<SharedString> = labels.into_iter().map(SharedString::from).collect();
    let separator = recents.len();
    let selected = current
        .as_ref()
        .and_then(|current| recents.iter().position(|model| model == current));
    let this = cx.weak_entity();
    let recents_for_choice = recents.clone();
    let popup = PopUpButton::new("composer-model", "Model", std::mem::take(&mut items))
        .selected(selected)
        .size(ControlSize::Small)
        .min_width(120.)
        .unselectable([separator])
        .on_choose(move |index, window, cx| {
            let _ = this.update(cx, |view, cx| {
                if let Some(model) = recents_for_choice.get(*index).cloned() {
                    view.switch_session_model(model, cx);
                } else if *index > separator {
                    view.open_choose_model_sheet(window, cx);
                }
            });
        });
    Some(popup.into_any_element())
}

/// Variants belong to the current model; a model without variants has no
/// selector. `Default` is the no-explicit-variant value.
fn render_composer_variant(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
    self.current_summary()?;
    let variants: Vec<String> = self
        .current_model_variants()
        .map(|variants| variants.iter().map(|variant| variant.id.clone()).collect())
        .unwrap_or_default();
    if variants.is_empty() {
        return None;
    }
    let mut items: Vec<SharedString> = vec!["Default".into()];
    items.extend(variants.iter().cloned().map(SharedString::from));
    let current = self
        .current_summary()
        .and_then(|summary| summary.model.as_ref())
        .and_then(|model| model.variant.clone());
    let selected = current
        .as_ref()
        .and_then(|current| variants.iter().position(|variant| variant == current))
        .map(|index| index + 1);
    let this = cx.weak_entity();
    let popup = PopUpButton::new("composer-variant", "Variant", items)
        .selected(selected.or(Some(0)))
        .size(ControlSize::Small)
        .min_width(96.)
        .on_choose(move |index, _, cx| {
            let variant = (*index)
                .checked_sub(1)
                .and_then(|index| variants.get(index).cloned());
            let _ = this.update(cx, |view, cx| view.set_model_variant(variant, cx));
        });
    let anchor = self.variant_bounds.clone();
    Some(
        div().relative().child(popup).child(
            gpui::canvas(
                |_, _, _| (),
                move |bounds, _, _, _| {
                    anchor.set(bounds);
                },
            )
            .absolute()
            .inset_0(),
        ),
    )
}

