/// Rebuilds the unified toolbar (HIG pp. 257–261). Toolbar items are
/// textured regular controls; nothing here reports status or counts.
fn render_toolbar(&self, window: &Window, cx: &mut Context<Self>) -> AnyElement {
    let width = f32::from(window.viewport_size().width);
    let show_effort = width >= 1180.0;
    let show_segmented = width >= 980.0;
    let show_identity = width >= 820.0;
    let search_width = if width >= 980.0 { 190. } else { 140. };

    let new_session = CommandButton::new(
        "toolbar-new-session",
        commands::SESSION_NEW,
        self.commands.clone(),
    )
    .size(ControlSize::Regular);
    let stop = CommandButton::new(
        "toolbar-stop",
        commands::SESSION_INTERRUPT,
        self.commands.clone(),
    )
    .size(ControlSize::Regular);
    let inspector = CommandButton::new(
        "toolbar-inspector",
        commands::INSPECTOR,
        self.commands.clone(),
    )
    .size(ControlSize::Regular);
    let inspector_help = if self.inspector.visible {
        "Hide the inspector"
    } else {
        "Show the inspector with the session, activity and output tabs"
    };

    let mut bar = div()
        .w_full()
        .h_full()
        .flex()
        .items_center()
        .gap(px(8.))
        .px(px(8.))
        .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
        .child(toolbar_help(
            "toolbar-new-session-help",
            "Create a session in a project",
            new_session,
        ))
        .child(toolbar_help(
            "toolbar-stop-help",
            "Stop the running session (unavailable while idle)",
            stop,
        ))
        .child(div().flex_1());

    if show_identity {
        if let Some(agent) = self.render_agent_popup(cx) {
            bar = bar.child(agent);
        }
        if let Some(model) = self.render_model_popup(cx) {
            bar = bar.child(model);
        }
    }
    if show_effort {
        bar = bar.child(self.render_effort_popup(cx));
    }
    bar = bar.child(div().flex_1());

    if show_segmented {
        let this = cx.weak_entity();
        let workspace = SegmentedControl::new(
            "toolbar-workspace",
            "Workspace",
            vec![
                Segment::new("conversation", "Conversation"),
                Segment::new("changes", "Changes"),
            ],
        )
        .style(SegmentStyle::Textured)
        .size(ControlSize::Regular)
        .selected(if self.changes_open {
            "changes"
        } else {
            "conversation"
        })
        .on_select(move |id, window, cx| {
            let changes = id.as_ref() == "changes";
            let _ = this.update(cx, |view, cx| {
                view.set_changes_visible(changes, window, cx);
            });
        });
        bar = bar.child(toolbar_help(
            "toolbar-workspace-help",
            "Switch between the conversation and this session's file changes",
            workspace,
        ));
        let this = cx.weak_entity();
        let detail = SegmentedControl::new(
            "toolbar-detail",
            "Transcript detail",
            vec![
                Segment::new("compact", "Compact"),
                Segment::new("detailed", "Detailed"),
            ],
        )
        .style(SegmentStyle::Textured)
        .size(ControlSize::Regular)
        .selected(if self.detailed { "detailed" } else { "compact" })
        .on_select(move |id, _, cx| {
            let detailed = id.as_ref() == "detailed";
            let _ = this.update(cx, |view, cx| view.set_detailed(detailed, cx));
        });
        bar = bar.child(toolbar_help(
            "toolbar-detail-help",
            "Compact shows answers and tool summaries; Detailed adds reasoning and activity",
            detail,
        ));
    } else {
        let this = cx.weak_entity();
        let selected = match (self.changes_open, self.detailed) {
            (false, false) => 0,
            (false, true) => 1,
            (true, _) => 2,
        };
        let view = PopUpButton::new(
            "toolbar-view",
            "View",
            vec![
                SharedString::from("Conversation"),
                SharedString::from("Conversation, Detailed"),
                SharedString::from("Changes"),
            ],
        )
        .selected(Some(selected))
        .size(ControlSize::Regular)
        .bezel(PopupStyle::Textured)
        .on_choose(move |index, window, cx| {
            let _ = this.update(cx, |view, cx| match index {
                0 => {
                    view.set_changes_visible(false, window, cx);
                    view.set_detailed(false, cx);
                }
                1 => {
                    view.set_changes_visible(false, window, cx);
                    view.set_detailed(true, cx);
                }
                _ => view.set_changes_visible(true, window, cx),
            });
        });
        bar = bar.child(toolbar_help(
            "toolbar-view-help",
            "Choose the conversation detail level or the session changes view",
            view,
        ));
    }

    bar = bar.child(toolbar_help(
        "toolbar-inspector-help",
        inspector_help,
        inspector,
    ));
    let search_box = div()
        .id("toolbar-search-box")
        .w(px(search_width))
        .flex_none()
        .capture_key_down(cx.listener(|view, event: &KeyDownEvent, _, cx| {
            if event.keystroke.key == "escape" {
                cx.stop_propagation();
                view.close_search(cx);
            } else if event.keystroke.key == "enter" && event.keystroke.modifiers.shift {
                cx.stop_propagation();
                view.navigate_search(false, cx);
            }
        }))
        .child(self.search_field.clone());
    bar = bar.child(toolbar_help(
        "toolbar-search-help",
        "Search this transcript as you type (Ctrl+F)",
        search_box,
    ));
    bar.into_any_element()
}

