    /// Bottom bar: only completed status strings; Sandcat owns every count and
    /// all wording. Zero-valued statuses are omitted.
    fn render_bottom_bar(&self, cx: &mut Context<Self>) -> BottomBar {
        let (label, _) = self.status_label();
        let side = if self.server_local { "Local" } else { "Remote" };
        let connection = format!("{label} \u{2014} {side}");
        let mut items = vec![BottomBarItem::status(
            BottomBarStatus::new("status-connection", connection)
                .help(format!("The configured OpenCode service is {side}.")),
        )];
        let subagents = self.running_subagents();
        let shells = self.running_shells();
        if subagents > 0 || shells > 0 {
            let mut activity = if subagents == 1 { "1 subagent".to_owned() } else { format!("{subagents} subagents") };
            if shells > 0 {
                activity.push_str(if shells == 1 { ", 1 shell running" } else { ", shells running" });
            }
            if self.active_session_busy() {
                activity.push_str(", session running");
            }
            let this = cx.weak_entity();
            items.push(BottomBarItem::status(
                BottomBarStatus::new("status-activity", activity)
                    .help("Running work in this session. Open the inspector's Activity tab.")
                    .on_activate(move |_, cx| {
                        let _ = this.update(cx, |view, cx| {
                            view.inspector.visible = true;
                            view.inspector_tab = InspectorTab::Activity;
                            view.publish_commands(cx);
                            cx.notify();
                        });
                    }),
            ));
        }
        let pending = self.pending_request_count();
        if pending > 0 {
            let this = cx.weak_entity();
            items.push(BottomBarItem::status(
                BottomBarStatus::new(
                    "status-pending",
                    if pending == 1 { "1 request waiting".to_owned() } else { format!("{pending} requests waiting") },
                )
                .help("Open the pending request sheet.")
                .on_activate(move |window, cx| {
                    let _ = this.update(cx, |view, cx| view.open_next_pending_request(window, cx));
                }),
            ));
        }
        if let Some(notice) = self.action_notice.clone().or_else(|| self.composer_state.notice().map(str::to_owned)) {
            items.push(BottomBarItem::flexible_space("status-notice-space"));
            items.push(BottomBarItem::status(BottomBarStatus::new("status-notice", notice)));
        }
        BottomBar::new("bottom-bar", "Status", items)
    }
