/// The bottom bar (HIG p. 212): at most three small status values, left
/// aligned, 12 px apart, and nothing zero-valued.
fn render_bottom_bar(&self, cx: &mut Context<Self>) -> AnyElement {
    let theme = cx.theme().clone();
    let ink = silvestris::convert::rgba(theme.colors.text);
    let (label, _) = self.status_label();
    let side = if self.server_local { "Local" } else { "Remote" };
    let connection = format!("{label} \u{2014} {side}");
    let mut bar = div()
        .h_full()
        .flex()
        .items_center()
        .gap(px(12.))
        .px(px(8.))
        .child(status::value(
            "status-connection",
            "",
            connection,
            format!("The configured OpenCode service is {side}."),
            ink,
            cx,
        ));
    let subagents = self.running_subagents();
    let shells = self.running_shells();
    if subagents > 0 || shells > 0 {
        let mut activity = if subagents == 1 {
            "1 subagent".to_owned()
        } else {
            format!("{subagents} subagents")
        };
        if shells > 0 {
            activity.push_str(if shells == 1 {
                ", 1 shell running"
            } else {
                ", shells running"
            });
        }
        let value = status::value(
            "status-activity",
            "",
            activity,
            "Running work in this session. Open the inspector's Activity tab.",
            ink,
            cx,
        )
        .cursor_pointer()
        .on_click(cx.listener(|view, _, _, cx| {
            view.inspector.visible = true;
            view.inspector_tab = InspectorTab::Activity;
            view.publish_commands(cx);
            cx.notify();
        }));
        if self.active_session_busy() {
            bar = bar.child(
                ProgressIndicator::spinner("status-spinner", "Session running")
                    .size(ControlSize::Small),
            );
        }
        bar = bar.child(value);
    }
    let pending = self.pending_request_count();
    if pending > 0 {
        let value = status::value(
            "status-pending",
            "",
            if pending == 1 {
                "1 request waiting".to_owned()
            } else {
                format!("{pending} requests waiting")
            },
            "Open the pending request sheet.",
            ink,
            cx,
        )
        .cursor_pointer()
        .on_click(cx.listener(|view, _, window, cx| {
            view.open_next_pending_request(window, cx);
        }));
        bar = bar.child(value);
    }
    if let Some(notice) = self
        .action_notice
        .clone()
        .or_else(|| self.composer_state.notice().map(str::to_owned))
    {
        bar = bar.child(div().flex_1()).child(
            div()
                .truncate()
                .text_size(px(theme.type_.size_small))
                .text_color(silvestris::convert::hsla(theme.colors.text_secondary))
                .child(notice),
        );
    }
    bar.into_any_element()
}

